// Phase 0 — the dispatch webhook is the only n8n entry point that can make the
// clinic send real messages and place real calls, so it is authenticated before
// anything else runs. Fail closed: an unset DJANGO_WEBHOOK_SECRET rejects every
// request (an unconfigured receiver never accepts traffic).
//
// Django sends the same value it uses for every X-Webhook-Secret call
// (ClinicSetting.webhook_secret -> settings.WEBHOOK_SECRET -> dev fallback).
const src = $input.first().json || {};
const headers = src.headers || {};

const env = (name) => { try { const v = $env[name]; return v == null ? '' : String(v); } catch (e) { return ''; } };

const expected = env('DJANGO_WEBHOOK_SECRET');
const provided = String(headers['x-webhook-secret'] || '').trim();
const authorized = Boolean(expected) && provided === expected;

return [{ json: {
  ...src,
  dispatch_auth: {
    authorized: authorized,
    reason: authorized ? null : (expected ? 'bad_secret' : 'secret_not_configured'),
  },
} }];

// Workflow 08 · Parse Disruption Items — the boundary between Django's words and
// the provider adapter. Django's auto-resolver queues one item per channel
// (claim_ref disrupt-<code>-<placement signature>-<channel>) carrying its OWN
// words; this node flattens
// the webhook body into one adapter input per item and sets the want_* flags from
// the item's channel. Django's words pass through VERBATIM — nothing here
// rewrites, truncates or re-templates patient copy.
//
// Fail-closed hygiene: an item missing a required field (message, claim_ref, a
// known channel, a destination phone) is DROPPED here, never half-delivered. A
// dropped item stays 'queued' in Django's log — visible to reception, retryable
// by re-push — so nothing is silently lost.
const req = $input.first().json || {};
const body = req.body || req;
const items = Array.isArray(body.items) ? body.items : [];

const KNOWN = ['sms', 'whatsapp'];
const out = [];
for (const item of items) {
  if (!item || typeof item !== 'object') continue;
  const channel = item.channel;
  if (!KNOWN.includes(channel)) continue;                          // unknown channel: nothing safe to send
  if (!item.claim_ref || !String(item.claim_ref).trim()) continue; // no claim: cannot stay single-shot
  if (!item.message || !String(item.message).trim()) continue;     // no words: never invent any
  if (!item.patient_phone || !String(item.patient_phone).trim()) continue; // no destination
  out.push({ json: {
    request_id: item.request_id || item.id || '', // the appointment code — what log nodes + callbacks key on
    patient_name: item.patient_name || '',
    patient_phone: String(item.patient_phone),
    service_name: item.service_name || '',
    doctor_name: item.doctor_name || body.doctor_name || '',
    clinic_name: body.clinic_name || '',
    reason: body.reason || '',
    start_datetime: item.start_datetime || '',
    channel: channel,
    claim_ref: String(item.claim_ref),
    message: String(item.message),
    chat_id: null,
    want_sms: channel === 'sms',
    want_whatsapp: channel === 'whatsapp',
    want_voice: false,
  } });
}
return out;

// Workflow 08 — Provider Config & Adapter (disruption notices) — single source of
// provider config. Reads deployment config from $env — no node hardcodes a URL,
// key or sender id. Django queues one claim row per channel, so Parse Disruption
// Items emits one input per channel and this node adapts EVERY input 1:1. One
// push carries every impacted patient — dropping items would silently strand
// patients (found live 2026-11-17: item[0]-only left 3 of 4 unsent).
//
// Mock mode (PROVIDER_MOCK unset or true) does NOT skip the send nodes: it points
// every provider URL at the in-cluster Provider Simulator (06_Provider_Simulator),
// so the real HTTP nodes, their bodies and the real failure path are exercised
// today. Flip-live = PROVIDER_MOCK=false + real VOICEBIP_* / WHATSAPP_* values.
//
// NO voice leg here by decision (2026-11-17): a disruption notice is a message,
// not a call — no voice nudge for disruptions.

const env = (name, fallback = '') => {
  try { const v = $env[name]; return (v === undefined || v === null) ? fallback : String(v); }
  catch (e) { return fallback; }
};
const truthy = (v) => ['1', 'true', 'yes', 'on'].includes(String(v).trim().toLowerCase());

const providerMock = env('PROVIDER_MOCK') === '' ? true : truthy(env('PROVIDER_MOCK'));

// ---- WhatsApp message mode -------------------------------------------------
// Meta rejects business-initiated free-form text outside the 24-hour customer
// service window, and a disruption notice always goes to a patient who has not
// messaged us recently. So 'template' is the only correct live mode. Django's
// disruption words are one full sentence — they do not fit the slot-offer
// template's six positional params — so this workflow has its OWN approved
// template name (WHATSAPP_DISRUPTION_TEMPLATE_NAME) whose body is a single
// {{1}} placeholder filled with Django's sentence, VERBATIM.
const waMode = (env('WHATSAPP_TEMPLATE_MODE', 'template') || 'template').trim().toLowerCase() === 'text'
  ? 'text' : 'template';
// In mock mode a placeholder name is assumed so the template body is still
// exercised by the simulator. Live mode stays empty until the template exists.
const waTemplateName = providerMock
  ? env('WHATSAPP_DISRUPTION_TEMPLATE_NAME', 'mock_clinic_disruption_notice')
  : env('WHATSAPP_DISRUPTION_TEMPLATE_NAME');
const waTemplateLang = env('WHATSAPP_TEMPLATE_LANG', 'en_US') || 'en_US';

const cfg = {
  voicebipApiUrl: env('VOICEBIP_API_URL'),
  voicebipApiKey: env('VOICEBIP_API_KEY'),
  smsSenderId: env('VOICEBIP_SMS_SENDER_ID', 'Cedarcare'),
  whatsappApiUrl: env('WHATSAPP_API_URL', 'https://graph.facebook.com/v19.0/'),
  whatsappPhoneId: env('WHATSAPP_PHONE_NUMBER_ID'),
  whatsappToken: env('WHATSAPP_ACCESS_TOKEN'),
  simulatorUrl: env('PROVIDER_SIMULATOR_URL', 'http://127.0.0.1:5678/webhook/provider-sim'),
};

// Dedupe guard (best-effort; static data is not persisted in manual test runs -
// Django's claim rows remain authoritative). One store for the whole push,
// keyed per appointment+channel.
let seenStore = null;
try {
  const sd = $getWorkflowStaticData('global');
  sd.seen = sd.seen || {};
  seenStore = sd.seen;
  const now = Date.now();
  for (const k of Object.keys(seenStore)) { if (now - seenStore[k] > 600000) delete seenStore[k]; }
} catch (e) { /* static data unavailable */ }

const adaptItem = (src) => {
  const requestId = src.request_id || ''; // the appointment code (AP-...)
  const patientPhone = src.patient_phone || '';

  // Meta wants E.164 without the plus; Django re-normalizes whatever comes back.
  const waTo = String(patientPhone).replace(new RegExp('[^0-9]', 'g'), '');

  // Django sends one item per channel (its claim rows are the single-shot guard),
  // so each input item activates exactly one channel.
  const active = [];
  if (src.want_whatsapp && !src.chat_id) active.push('whatsapp');
  if (src.want_sms) active.push('sms');

  const configured = providerMock
    ? { whatsapp: true, sms: true }
    : {
        sms: Boolean(cfg.voicebipApiUrl && cfg.voicebipApiKey),
        whatsapp: Boolean(cfg.whatsappPhoneId && cfg.whatsappToken),
      };

  const seen = {};
  for (const ch of active) seen[ch] = Boolean(seenStore && seenStore[requestId + ':' + ch]);

  // ---- WhatsApp body --------------------------------------------------------
  // The approved disruption template's body is ONE placeholder: {{1}} = Django's
  // full sentence, verbatim. No quick-reply buttons — a disruption notice asks
  // nothing (2026-11-17 decision: no new reply grammar).
  const buildWhatsAppBody = () => {
    if (waMode === 'text') {
      return {
        messaging_product: 'whatsapp',
        to: waTo,
        type: 'text',
        text: { body: src.message || '' },
        biz_opaque_callback_data: requestId,
      };
    }
    return {
      messaging_product: 'whatsapp',
      to: waTo,
      type: 'template',
      template: {
        name: waTemplateName,
        language: { code: waTemplateLang },
        components: [{
          type: 'body',
          parameters: [{ type: 'text', text: src.message || '' }],
        }],
      },
      // Meta echoes this in every status callback, which is how a real wamid is
      // linked back to the appointment (nothing else survives the round trip).
      biz_opaque_callback_data: requestId,
    };
  };

  const buildRequest = (channel) => {
    if (channel === 'whatsapp') {
      const headers = providerMock
        ? { Authorization: 'Bearer mock' }
        : { Authorization: 'Bearer ' + cfg.whatsappToken };
      const url = providerMock
        ? cfg.simulatorUrl + '/whatsapp'
        : cfg.whatsappApiUrl + cfg.whatsappPhoneId + '/messages';
      return { url, headers, body: buildWhatsAppBody() };
    }

    if (providerMock) {
      // Same request shape, different destination: the simulator answers in-cluster.
      return {
        url: cfg.simulatorUrl + '/' + channel,
        headers: { Authorization: 'Bearer mock' },
        body: { to: patientPhone, message: src.message || '', sender_id: cfg.smsSenderId,
                metadata: { request_code: requestId, channel } },
      };
    }

    return {
      url: cfg.voicebipApiUrl + '/sms',
      headers: { Authorization: 'Bearer ' + cfg.voicebipApiKey },
      body: { to: patientPhone, message: src.message || '', sender_id: cfg.smsSenderId,
              metadata: { request_code: requestId, channel: 'sms' } },
    };
  };

  // Why a channel will not fire, most fundamental first: a repeat (duplicate), a
  // patient with no number (nothing can be sent), a channel whose credentials are
  // absent, and finally a configured WhatsApp leg with no approved template.
  const skipReasonFor = (channel) => {
    if (seen[channel]) return 'duplicate_dispatch';
    if (!patientPhone) return 'missing_phone';
    if (!configured[channel]) return 'provider_not_configured';
    if (channel === 'whatsapp' && waMode === 'template' && !waTemplateName) return 'whatsapp_template_not_configured';
    return null;
  };

  const out = active.map((channel) => {
    const skipReason = skipReasonFor(channel);
    const route = skipReason ? 'skip' : channel;
    // Never build a request for a channel that will not send: a skipped leg has no
    // URL, and nothing downstream can accidentally use one.
    const request = skipReason ? { url: '', headers: {}, body: null } : buildRequest(channel);

    return { json: {
      ...src,
      provider_channel: channel,
      provider_request: {
        route,
        skip_reason: skipReason,
        method: 'POST',
        ...request,
      },
      adapter_meta: {
        channel,
        provider_mock: providerMock,
        configured: configured[channel],
        duplicate: Boolean(seen[channel]),
        request_id: requestId,
        claim_ref: src.claim_ref || '',
        whatsapp_mode: channel === 'whatsapp' ? waMode : null,
        whatsapp_template: channel === 'whatsapp' && waMode === 'template' ? waTemplateName : null,
        external_ref_hint: channel === 'whatsapp'
          ? ('wamid.mock-whatsapp-' + requestId)
          : ('mock-' + channel + '-' + requestId),
        missing_env: providerMock ? [] : Object.entries({
          VOICEBIP_API_URL: cfg.voicebipApiUrl,
          VOICEBIP_API_KEY: cfg.voicebipApiKey,
          WHATSAPP_PHONE_NUMBER_ID: cfg.whatsappPhoneId,
          WHATSAPP_ACCESS_TOKEN: cfg.whatsappToken,
          WHATSAPP_DISRUPTION_TEMPLATE_NAME: waTemplateName,
          DJANGO_WEBHOOK_SECRET: env('DJANGO_WEBHOOK_SECRET'),
        }).filter(([, v]) => !v).map(([k]) => k),
      },
    } };
  });

  // Stamp the dedupe window only for the legs that will actually fire. A skip means
  // no provider was contacted, so the window stays open for the retry that fixes it.
  if (seenStore) {
    const stampedAt = Date.now();
    for (const item of out) {
      const channel = item.json.provider_channel;
      const request = item.json.provider_request;
      if (channel && request && request.skip_reason === null) {
        seenStore[requestId + ':' + channel] = stampedAt;
      }
    }
  }

  return out;
};

// EVERY input item is adapted — one push carries every impacted patient.
const results = $input.all().flatMap((item) => adaptItem(item.json));

if (seenStore) {
  // (per-item stamping already applied inside adaptItem)
}

return results.length
  ? results
  : [{ json: {
      ...((($input.all()[0] || {}).json || {})),
      provider_channel: null,
      provider_request: { route: 'no_active_channel', skip_reason: 'no_active_channel', method: 'POST', url: '', headers: {}, body: null },
      adapter_meta: { channel: null, provider_mock: providerMock, configured: false, duplicate: false, request_id: '', claim_ref: '', whatsapp_mode: null, whatsapp_template: null, external_ref_hint: null, missing_env: [] },
    } }];

// Workflow 08 · Stage D-3 — log the provider outcome to Django (authoritative record).
// One disruption push carries EVERY impacted patient, so unlike Workflow D this
// node zips EVERY response with the adapter's same-channel items BY POSITION
// (the send nodes preserve order). The provider-error-classification block below
// is the canonical copy shared with Workflow D (test_lognodes.js asserts that).
const responses = $input.all();
const bases = $('Provider Config & Adapter').all()
  .map(i => i.json)
  .filter(j => j && j.provider_channel === 'whatsapp');

// >>> provider-error-classification (canonical copy — byte-identical in all three
// Log * Interaction nodes; test_lognodes.js asserts that) >>>
// n8n hands a failed HTTP call to this node as { message, name, stack } — plus a
// `code` for transport errors. There is NO error.status: the status only exists as
// the message prefix, and the response body is embedded as a JSON *string literal*:
//   404 - "{\"code\":404,\"message\":\"...\"}"
// So the status must be read from the prefix and the body needs a real two-step parse.
const STATUS_LABEL = {
  400: 'Provider rejected the request',
  401: 'Provider authentication failed',
  403: 'Provider refused access',
  404: 'Provider endpoint not found',
  409: 'Provider reported a conflict',
  422: 'Provider rejected the request',
  429: 'Provider rate limit reached',
};
const TRANSPORT_LABEL = {
  ECONNREFUSED: 'Provider endpoint refused the connection',
  ENOTFOUND: 'Provider host could not be resolved',
  ETIMEDOUT: 'Provider did not respond in time',
  ECONNABORTED: 'Provider did not respond in time',
  ECONNRESET: 'Provider closed the connection',
};

// Display-only clean-up: one line, no escape residue, no wrapping quotes.
const tidy = (value) => {
  if (typeof value === 'number') return String(value);
  if (typeof value !== 'string') return '';
  return value
    .replace(/\\[nrt]/g, ' ')
    .replace(/\\"/g, '"')
    .replace(/^["']|["']$/g, '')
    .replace(/\s+/g, ' ')
    .trim();
};

// Decode the embedded body: JSON string literal -> JSON payload. A hand-rolled
// .replace(/\\"/g, '"') is NOT equivalent: it corrupts nested escaped quotes and
// the parse then throws, which is how the raw wrapper used to reach reception.
const asObject = (body) => {
  let value = String(body == null ? '' : body).trim();
  for (let i = 0; i < 3; i += 1) {
    if (value[0] === '{') {
      try { return JSON.parse(value); } catch (e) { return null; }
    }
    if (value[0] !== '"') return null;
    const end = value.lastIndexOf('"');
    if (end <= 0) return null;
    try { value = JSON.parse(value.slice(0, end + 1)); } catch (e) { return null; }
  }
  return null;
};

const firstText = (list) => {
  if (!Array.isArray(list)) return '';
  for (const item of list) {
    const text = tidy(typeof item === 'string' ? item : (item && (item.message || item.detail || item.msg)));
    if (text) return text;
  }
  return '';
};

// The provider's own sentence, in the order providers actually use it.
const providerSentence = (body) => {
  const parsed = asObject(body);
  if (!parsed) return tidy(body);
  const err = parsed.error;
  const candidates = [
    parsed.detail, parsed.message, parsed.error_description, parsed.description, parsed.hint,
    typeof err === 'string' ? err : '',
    err && err.message, err && err.title,
    err && err.error_data && err.error_data.details,
    firstText(parsed.errors),
  ];
  for (const candidate of candidates) {
    const text = tidy(candidate);
    if (text) return text;
  }
  return tidy(body);
};

// -> { status: number|null, detail: string (<=300) } — one sentence reception can act on.
const classifyProviderError = (err) => {
  // Parse from the RAW message: tidy() unescapes quotes and must never run first,
  // or the JSON string literal stops being a valid literal.
  const message = (err && typeof err.message === 'string') ? err.message : '';
  const explicit = Number(err && (err.status || err.httpCode || err.statusCode));
  const prefixed = message.match(/^\s*(\d{3})\s*-\s*([\s\S]*)$/);
  const status = (Number.isFinite(explicit) && explicit >= 400) ? explicit
    : (prefixed ? Number(prefixed[1]) : null);
  if (status) {
    const label = STATUS_LABEL[status] || (status >= 500 ? 'Provider server error' : 'Provider returned an error');
    const sentence = providerSentence(prefixed ? prefixed[2] : '');
    return { status, detail: (label + (sentence ? ': ' + sentence : '')).slice(0, 300) };
  }
  const code = tidy(err && err.code).toUpperCase();
  if (TRANSPORT_LABEL[code]) return { status: null, detail: TRANSPORT_LABEL[code].slice(0, 300) };
  return { status: null, detail: (tidy(message) || tidy(err) || 'Provider call failed').slice(0, 300) };
};
// <<< provider-error-classification <<<

const SUMMARY = 'Disruption notice sent via WhatsApp';

const out = [];
for (let idx = 0; idx < responses.length; idx += 1) {
  const incoming = responses[idx].json || {};
  const base = bases[idx] || {};
  const isError = Boolean(incoming.error);
  const resp = isError ? {} : incoming;

  const providerStatus = String(resp.status || '').toLowerCase();
  const failed = isError || providerStatus === 'failed' || resp.ok === false;

  // A failed call is classified into one readable sentence; a provider that answers
  // ok:false (no exception) keeps its own message verbatim.
  const classified = isError ? classifyProviderError(incoming.error) : null;
  const errorDetail = isError
    ? classified.detail
    : (failed ? String(resp.error_message || resp.error || resp.detail || 'Provider reported a failure').slice(0, 300) : '');

  const payload = {
    provider: 'meta_whatsapp',
    channel: 'whatsapp',
    direction: 'outbound',
    status: failed ? 'failed' : 'sent',
    patient_name: base.patient_name || '',
    patient_phone: base.patient_phone || '',
    request_code: base.request_id || '',
    external_ref: failed ? '' : (
      (resp.messages && resp.messages[0] && resp.messages[0].id) ||
      resp.external_ref || resp.message_id || resp.id || resp.call_id || ''
    ),
    claim_ref: base.claim_ref || '',
    summary: SUMMARY,
    error_detail: errorDetail,
  };

  let logged = { ok: false };
  try {
    const res = await this.helpers.httpRequest({
      method: 'POST',
      url: $env.DJANGO_API_BASE_URL + '/interactions/',
      headers: { 'Content-Type': 'application/json', 'X-Webhook-Secret': $env.DJANGO_WEBHOOK_SECRET || '' },
      body: payload,
      json: true,
    });
    logged = { ok: true, id: res.id, status: res.status };
  } catch (e) {
    logged = { ok: false, error: (e.message || String(e)).slice(0, 300) };
  }

  out.push({ json: { ...base, provider_response: resp, interaction_log: { ...logged, payload } } });
}
return out;

