  const classified = isError ? classifyProviderError(incoming.error) : null;
  const errorDetail = isError
    ? classified.detail
    : (failed ? String(resp.error_message || resp.error || resp.detail || 'Provider reported a failure').slice(0, 300) : '');

  const payload = {
    provider: 'voicebip',
    channel: 'sms',
    direction: 'outbound',
    status: failed ? 'failed' : 'sent',
    patient_name: base.patient_name || '',
    patient_phone: base.patient_phone || '',
    request_code: base.request_id || '',
    external_ref: failed ? '' : (
      (resp.messages && resp.messages[0] && resp.messages[0].id) ||
      resp.external_ref || resp.message_id || resp.id || resp.call_id || ''
    ),
    claim_ref: base.claim_ref || '',
    summary: SUMMARY,
    error_detail: errorDetail,
  };

  let logged = { ok: false };
  try {
    const res = await this.helpers.httpRequest({
      method: 'POST',
      url: $env.DJANGO_API_BASE_URL + '/interactions/',
      headers: { 'Content-Type': 'application/json', 'X-Webhook-Secret': $env.DJANGO_WEBHOOK_SECRET || '' },
      body: payload,
      json: true,
    });
    logged = { ok: true, id: res.id, status: res.status };
  } catch (e) {
    logged = { ok: false, error: (e.message || String(e)).slice(0, 300) };
  }

  out.push({ json: { ...base, provider_response: resp, interaction_log: { ...logged, payload } } });
}
return out;

// Workflow D · Phase 2 — skip visibility.
// The switch's skip output used to end in nowhere: a channel the receptionist
// asked for that could not fire vanished into the execution log. This node
// writes a `queued` InteractionLog row ("held back, not attempted") for every
// actionable skip, so Django — the source of truth — can show reception what
// was NOT sent and why.
//
// Row-worthy reasons (each one is actionable):
//   outside_call_window, provider_not_configured,
//   whatsapp_template_not_configured, missing_phone, no_slots,
//   voice_payload_missing.
// Not row-worthy, by decision:
//   duplicate_dispatch     — the original send row already exists.
//   no_active_channel      — the only real cause is a Telegram patient, and
//                            Django itself already logged the Telegram card.
//   patient_already_engaged — the patient has a hold or booking; reception can
//                            already see it, and the guard suppressed a nudge.
//
// This node is fed by the switch's skip output AND, since Phase 3 / 3.8, by the
// false output of `IF Voice Still Needed`: a voice payload that cannot be rebuilt
// after the 30s probe is the same kind of fact as any other held-back leg.
//
// The external_ref is deterministic (skip-<channel>-<request_code>), so a
// repeated skip updates the same row instead of piling up. A later real send
// uses a different ref — the history stays honest.
//
// Best-effort by design: a Django outage or a 400 must never fail the dispatch.
// The skip already happened; the row is a record, not a gate.
const REASON_TEXT = {
  outside_call_window: 'Outside calling hours (08:00-19:00) - the call was not placed.',
  provider_not_configured: 'Provider is not configured yet - credentials are missing.',
  whatsapp_template_not_configured: 'WhatsApp template not approved yet - nothing can be sent outside the 24-hour reply window without it.',
  missing_phone: 'No phone number on file for this patient.',
  no_slots: 'No free slot was found for this request - nothing was sent. Re-check availability before re-dispatching.',
  voice_payload_missing: 'The call could not be built after the 30-second check, so no call was placed. This means the dispatch ran twice or the adapter step did not produce the voice item - re-dispatch the request and check the execution log.',
};
const PROVIDER_FOR_CHANNEL = { whatsapp: 'meta_whatsapp', sms: 'voicebip', voice: 'voicebip' };

const out = [];
for (const item of $input.all()) {
  const j = item.json || {};
  const channel = j.provider_channel;
  const reason = j.provider_request && j.provider_request.skip_reason;
  const requestCode = j.request_id || '';

  const rowWorthy = Boolean(REASON_TEXT[reason] && channel && requestCode);
  let logged = { ok: false, skipped: 'not_row_worthy' };

  if (rowWorthy) {
    const payload = {
      provider: PROVIDER_FOR_CHANNEL[channel] || 'voicebip',
      channel: channel,
      direction: 'outbound',
      status: 'queued',
      patient_name: j.patient_name || '',
      // Blank by design for missing_phone; Django accepts it for queued rows
      // linked to a request (Phase 2 relaxation).
      patient_phone: j.patient_phone || '',
      request_code: requestCode,
      external_ref: 'skip-' + channel + '-' + requestCode,
      summary: 'Held back: ' + REASON_TEXT[reason],
      error_detail: reason,
    };
    try {
      const res = await this.helpers.httpRequest({
        method: 'POST',
        url: $env.DJANGO_API_BASE_URL + '/interactions/',
        headers: { 'Content-Type': 'application/json', 'X-Webhook-Secret': $env.DJANGO_WEBHOOK_SECRET || '' },
        body: payload,
        json: true,
      });
      logged = { ok: true, id: res.id, status: res.status };
    } catch (e) {
      logged = { ok: false, error: String(e.message || e).slice(0, 300) };
    }
    logged.payload = payload;
  }

  out.push({ json: { ...j, skip_log: logged } });
}
return out;

// Workflow 08 - Stage C.2 - ask Django before speaking.
//
// Django queues a notice (status 'queued') and then this workflow delivers it.
// Between those two moments the plan can be undone: Django marks the notice
// 'expired' because the times it names no longer hold. "queued" therefore
// means "not sent yet", NOT "never will be". A patient must never receive
// words that were withdrawn, so every item is checked against Django
// immediately before any send node runs.
//
// Fail closed: only a definite `live: true` lets an item through. An
// unreachable Django, a 401, a body without `claims`, a claim Django does not
// know, or a missing configuration all hold the item. A held item stays in
// Django's log exactly as it was (still 'queued', or already 'expired'), so
// reception sees it and can re-push once the plan settles. Nothing is
// rewritten here and no patient copy is produced.
//
// Output feeds "IF Claim Live": true -> Provider Config & Adapter (send path),
// false -> Log Halted Claims (a dead end, by design).
const items = $input.all().map((i) => i.json).filter((j) => j && j.claim_ref);

if (items.length === 0) return [];

const base = String($env.DJANGO_API_BASE_URL || '').replace(/\/+$/, '');
const secret = String($env.DJANGO_WEBHOOK_SECRET || '');

const refs = [];
for (const item of items) {
  const ref = String(item.claim_ref);
  if (!refs.includes(ref)) refs.push(ref);
}

let claims = null;
if (base && secret) {
  try {
    const answer = await this.helpers.httpRequest({
      method: 'POST',
      url: base + '/webhooks/disruption-claims/check/',
      headers: { 'Content-Type': 'application/json', 'X-Webhook-Secret': secret },
      body: { claim_refs: refs },
      json: true,
    });
    if (answer && answer.claims && typeof answer.claims === 'object') {
      claims = answer.claims;
    }
  } catch (e) {
    claims = null; // Django did not answer a question we cannot guess
  }
}

const out = [];
for (const item of items) {
  const claim = claims ? claims[String(item.claim_ref)] : null;

  if (claim && claim.live === true) {
    out.push({ json: Object.assign({}, item, {
      claim_live: true,
      claim_status: claim.status ? String(claim.status) : 'queued',
      held_reason: null,
    }) });
    continue;
  }

  const status = claim && claim.status ? String(claim.status) : 'unknown';
  let reason = 'claim_unknown';
  if (!claims) reason = 'claim_check_unavailable';
  else if (status === 'expired') reason = 'claim_expired';
  else if (status === 'sent' || status === 'delivered' || status === 'answered') {
    reason = 'claim_already_sent';
  }

  console.warn('[disruption] holding ' + item.claim_ref + ': ' + reason
    + ' (claim status ' + status + ')');
  out.push({ json: Object.assign({}, item, {
    claim_live: false,
    claim_status: status,
    held_reason: reason,
  }) });
}
return out;

// Workflow 08 - Stage C.3 - the dead end for claims Django refused.
//
// One row per held claim: enough for a log reader to see what was stopped and
// why, and nothing else. No send, and no write back to Django: the notice is
// already visible there (still 'queued' if the check was unreachable, or
// 'expired' if the plan was undone). Rewriting it from here would either
// claim a send that never happened or turn an operational hold into a
// permanent expiry.
const held = $input.all().map((i) => i.json).filter((j) => j && j.claim_ref);

return held.map((item) => ({ json: {
  request_id: item.request_id || '',
  claim_ref: String(item.claim_ref),
  channel: item.channel || '',
  held_reason: item.held_reason || 'claim_unknown',
  claim_status: item.claim_status || 'unknown',
  sent: false,
} }));
